  `narasi_2` varchar(255) DEFAULT 'Persediaan PDP – Si Kertas per 30 November terdiri dari ',
  `narasi_3` varchar(255) DEFAULT 'PT. MITRA ANTAR POLINDO MALANG ',
  `narasi_4` varchar(255) DEFAULT 'NO. BM: 03 /BM/12/2021',
  `narasi_5` varchar(255) DEFAULT 'Penyesuaian kembali Persediaan Produk Dalam Proses Seksi Kertas per 1 Desember 2020 sebesar ',
  `narasi_6` varchar(255) DEFAULT ' ke barang dalam proses sie Kertas, terdiri dari ',
  `updated_by` int(11) DEFAULT 0,
  `last_scen` int(11) DEFAULT 0,
