INSERT INTO `gs3_config` (`id`, `title`, `deskripsi`, `info`, `narasisoal`, `narasi_1`, `narasi_2`, `narasi_3`, `narasi_4`, `narasi_5`, `narasi_6`, `updated_by`, `last_scen`, `created_date`, `updated_date`) VALUES
(3, 'Game Simulasi 3', 'Game .....', '', '<p><strong>Game Simulasi 3 - Bukti Memorial - Readjustment</strong><br><br>Pada Game Simulasi 3 ini mahasiswa diminta untuk membuat <strong>Bukti Memorial</strong> atas penyesuaian kembali Produk Dalam Proses (PDP).<br>Langkah-langkah pengerjaan Game Simulation 3 adalah sebagai berikut:<br>1. Hitung dan isi <strong>Total Persediaan PDP</strong> pada lembar kerja yang telah disediakan dengan melihat data persediaan PDP per 30 November.<br>2. Isi <strong>jumlah masing-masing rincian persediaan PDP</strong> yang terdiri dari Biaya Bahan Baku, Biaya Bahan Penolong, Biaya Tenaga Kerja, dan Biaya Overhead <br>    Pabrik dengan <span style=\"color: rgba(0,0,0,0.87);background-color: rgb(255,255,255);font-size: 14px;font-family: Roboto, Helvetica, Arial, sans-serif;\">melihat data persediaan PDP per 30 November.</span> <br>3. Cek kebenaran jawaban dengan cara klik tombol <strong>Check</strong>.<br>4. Selanjutnya seret (<em>drag</em>) isian <strong>Kode Akun</strong> dari Data Informasi dan lepas (<em>drop</em>) pada lembar kerja yang telah disediakan.<br>5. <span style=\"color: rgba(0,0,0,0.87);background-color: rgb(255,255,255);font-size: 14px;font-family: Roboto, Helvetica, Arial, sans-serif;\">Selanjutnya seret (<em>drag</em>) isian <strong>Jumlah Persediaan PDP</strong> dari Bukti Memorial dan lepas (<em>drop</em>) pada lembar kerja yang telah disediakan.</span> <br>6. <span style=\"color: rgba(0,0,0,0.87);background-color: rgb(255,255,255);font-size: 14px;font-family: Roboto, Helvetica, Arial, sans-serif;\">Cek kebenaran jawaban dengan cara klik tombol <strong>Check</strong>.</span>&nbsp;</p>\n', 'PERSEDIAAN PRODUK DALAM PROSES – SIE KERTAS', 'Persediaan PDP – Si Kertas per 30 November terdiri dari', 'PT. MITRA ANTAR POLINDO MALANG', 'NO. BM: 03 /BM/12/2021', 'Penyesuaian kembali Persediaan Produk Dalam Proses Seksi Kertas per 1 Desember 2020 sebesar', 'ke barang dalam proses sie Kertas, terdiri dari', NULL, NULL, NULL, NULL),
