INSERT INTO `items` (`id`, `spotid`, `name`, `description`, `ytlink`, `position`, `updated`) VALUES
(254, 79, 'Stove', 'A stove is a device that burns fuel or uses electricity to generate heat inside or on top of the apparatus. It has seen many developments over time and serves the main purpose of cooking food.', '', '1.2514833430306194 -1.0575065406376356 -16.510127543847105', '2021-08-26 06:52:31'),
(255, 79, 'Wastafel', 'also known by other names including sinker, washbowl, hand basin, wash basin, and simply basin – is a bowl-shaped plumbing fixture used for washing hands, dishwashing, and other purposes.', '', '9.463003112757002 -3.218539169974178 -13.75108482803196', '2021-08-26 06:52:31'),
(265, 85, 'Hanging Lounge Chair', 'A hanging chair is a type of chair with no legs that is instead mounted to a ceiling or support unit by a chain, rope, or other support. The chair is often freehanging, meaning it can swing or otherwise move freely.', '', '-0.3537115192374996 -0.8907224399553472 16.882928624585436', '2021-11-15 12:03:29'),
(275, 85, 'door', '', '', '-8.93683431252406 -1.7297852752182403 21.281928426748763', '2021-11-15 12:03:29'),
(287, 87, 'Conveyor Barang', 'conveyor dengan komponen rantai yang tersusun dan terhubung yang berfungsi untuk melakukan tarikan dari unit penggerak sehingga mampu membawa beberapa produk sekaligus dalam satu rangkaian.', '', '7.200790682984885 -5.15975842786573 13.948355528349223', '2022-01-07 07:53:15');

