  `created_date` datetime(6) DEFAULT NULL,
  `updated_date` datetime(6) DEFAULT NULL,
  `status_delete` int(11) DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `randomize` tinyint(1) DEFAULT NULL
