--
-- Table structure for table `taxpayer`
--

CREATE TABLE `taxpayer` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `taxpayer_type` enum('individual','company') NOT NULL,
  `has_nik` tinyint(1) NOT NULL,
  `registration_type` enum('nik-activation','registration-only') NOT NULL,
  `nik` varchar(16) NOT NULL,
  `full_name` varchar(200) NOT NULL,
  `place_of_birth` varchar(100) NOT NULL,
  `date_of_birth` date NOT NULL,
  `taxpayer_category` varchar(100) NOT NULL,
  `country_of_origin` varchar(50) NOT NULL,
  `religion` varchar(50) NOT NULL,
  `gender` enum('Male','Female') NOT NULL,
  `marital_status` varchar(50) NOT NULL,
  `type_of_work` varchar(100) NOT NULL,
  `mother_name` varchar(100) NOT NULL,
  `family_card_number` varchar(20) NOT NULL,
  `family_relationship_status` varchar(50) NOT NULL,
  `email` varchar(200) NOT NULL,
  `handphone` varchar(15) NOT NULL,
  `telephone` varchar(15) DEFAULT '',
  `fax` varchar(15) DEFAULT '',
  `economic_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`economic_data`)),
  `addresses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`addresses`)),
  `related_persons` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`related_persons`)),
  `registration_status` enum('pending','approved','rejected') DEFAULT 'pending',
  `approved_by` int(11) DEFAULT NULL,
  `approved_date` datetime DEFAULT NULL,
  `rejection_reason` text DEFAULT NULL,
  `status_delete` int(11) DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `created_date` datetime(6) DEFAULT NULL,
  `updated_date` datetime(6) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

